// Helper function to build rule equivalents map
import { ConversionError } from "../errors/conversionError";
import { TSLintConfigurationRules } from "../input/findTSLintConfiguration";
import { RuleConverter } from "./converter";
import { convertRule } from "./convertRule";
import { formatRawTslintRule } from "./formats/formatRawTslintRule";

export const buildRuleEquivalents = (
    converters: Map<string, RuleConverter>,
    rawTslintRules?: TSLintConfigurationRules,
): Map<string, string[]> => {
    const ruleEquivalents = new Map<string, string[]>();

    if (rawTslintRules === undefined) {
        return ruleEquivalents;
    }

    for (const [tslintRuleName, value] of Object.entries(rawTslintRules)) {
        const tslintRule = formatRawTslintRule(tslintRuleName, value);
        const conversion = convertRule(tslintRule, converters);

        if (conversion !== undefined && !(conversion instanceof ConversionError)) {
            const eslintRuleNames = conversion.rules.map((rule) => rule.ruleName);
            if (eslintRuleNames.length > 0) {
                ruleEquivalents.set(tslintRuleName, eslintRuleNames);
            }
        }
    }

    return ruleEquivalents;
};
