import * as ts from "typescript";

import { RuleConverter } from "../rules/converter";
import { uniqueFromSources } from "../utils";
import { ConversionError } from "../errors/conversionError";
import { FileComment } from "./parseFileComments";

export const replaceFileComments = (
    content: string,
    comments: FileComment[],
    converters: Map<string, RuleConverter>,
    ruleConversionCache: Map<string, string[]>,
    ruleEquivalents: Map<string, string[]>,
) => {
    const getNewRuleLists = (ruleName: string): string | undefined => {
        // First check the global rule equivalents cache (from config conversion)
        if (ruleEquivalents.has(ruleName)) {
            return ruleEquivalents.get(ruleName)!.join(", ");
        }

        // Then check the local file cache
        if (ruleConversionCache.has(ruleName)) {
            const cached = ruleConversionCache.get(ruleName);
            return cached?.join(", ");
        }

        // Fall back to converting with empty arguments (for rules not in tslint.json)
        const converter = converters.get(ruleName);
        if (converter === undefined) {
            ruleConversionCache.set(ruleName, []);
            return undefined;
        }

        const converted = converter({ ruleArguments: [] });
        const result = converted instanceof ConversionError
            ? []
            : converted.rules.map((conversion) => conversion.ruleName);

        ruleConversionCache.set(ruleName, result);
        return result.length > 0 ? result.join(", ") : undefined;
    };

    for (const comment of [...comments].reverse()) {
        const directive = comment.directive.replace("tslint:", "eslint-");
        const ruleLists = uniqueFromSources(comment.ruleNames.map(getNewRuleLists)).filter(Boolean);
        const [left, right] =
            comment.commentKind === ts.SyntaxKind.SingleLineCommentTrivia &&
            comment.directive !== "tslint:disable" &&
            comment.directive !== "tslint:enable"
                ? ["// ", ""]
                : ["/* ", " */"];

        content = [
            content.slice(0, comment.pos),
            left,
            directive,
            ruleLists.length !== 0 && " ",
            ruleLists.join(", "),
            right,
            content.slice(comment.end),
        ]
            .filter(Boolean)
            .join("");
    }

    return content;
};

